def prepare_conditioning(time_emb, class_emb):
    """Adaptive multiplicative conditioning: class embedding modulates time features
    via a learned gating function, combined with an additive residual.

    The multiplicative path allows class-specific feature selection in the time
    embedding, while the additive path preserves the raw class signal. This dual
    path gives richer conditioning than pure addition (concat-film) or identity.
    """
    gate = torch.sigmoid(class_emb)
    return time_emb * gate + class_emb


class ClassConditioner(nn.Module):
    """Cross-attention conditioning (same as baseline, zero-init ensures stability)."""
